import { useState, useRef, useEffect } from 'react';
import Logo from './Logo';
import { useROICanvas } from '../hooks/useCanvas';

const PROCESSING_STEPS = [
  'Decomposing spatial frequencies…',
  'Extracting local phase per sub-band…',
  'Applying Butterworth band-pass filter…',
  'Amplifying phase components (×8)…',
  'Reconstructing frames…',
  'Running FFT vibration analysis…',
  'Identifying dominant frequency…',
  'Generating report…',
];

const PRESETS = [
  { id: 'engine',     name: 'Engine / Motor',  tag: '10–200 Hz', desc: 'Rotating machinery'   },
  { id: 'structural', name: 'Structural Flex',  tag: '0.1–50 Hz', desc: 'Buildings & bridges'  },
  { id: 'custom',     name: 'Custom Range',     tag: 'User-defined', desc: 'Manual Hz input'   },
];

const SETTINGS = [
  { name: 'Amplification Factor', hint: 'Recommended',   value: '8×'      },
  { name: 'Temporal Filter',      hint: 'Bandpass',       value: 'Ideal BPF' },
  { name: 'Frame Sampling',       hint: 'Auto-detected',  value: '30 fps'  },
  { name: 'Color Map',            hint: 'Displacement',   value: 'Jet (HSV)' },
];

/* ── Processing overlay ── */
function ProcessingOverlay({ onComplete }) {
  const [step,     setStep]     = useState(0);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const total    = 3800;
    const interval = total / PROCESSING_STEPS.length;
    let elapsed    = 0;
    let stepIdx    = 0;

    const id = setInterval(() => {
      elapsed += interval;
      const pct = Math.min((elapsed / total) * 100, 100);
      setProgress(pct);
      if (stepIdx < PROCESSING_STEPS.length) setStep(stepIdx++);
      if (elapsed >= total) {
        clearInterval(id);
        setTimeout(onComplete, 400);
      }
    }, interval);

    return () => clearInterval(id);
  }, [onComplete]);

  return (
    <div className="processing-overlay">
      <div className="processing-card">
        <div className="processing-spinner">
          <svg width="56" height="56" viewBox="0 0 56 56">
            <circle cx="28" cy="28" r="24" stroke="#e5e7eb" strokeWidth="3" fill="none" />
            <circle cx="28" cy="28" r="24" stroke="#E8741A" strokeWidth="3" fill="none"
              strokeDasharray="100 50" strokeDashoffset="0" strokeLinecap="round">
              <animateTransform attributeName="transform" type="rotate"
                from="0 28 28" to="360 28 28" dur="1s" repeatCount="indefinite" />
            </circle>
          </svg>
        </div>
        <h3 className="processing-title">Analyzing Motion</h3>
        <p className="processing-sub">{PROCESSING_STEPS[step]}</p>
        <div className="processing-bar-wrap">
          <div className="processing-bar-fill" style={{ width: `${progress}%` }} />
        </div>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   UPLOAD PAGE
════════════════════════════════════════════════════════ */
export default function UploadPage({ onNavigate, onAnalysisComplete }) {
  const [file,        setFile]        = useState(null);
  const [videoURL,    setVideoURL]    = useState(null);
  const [isDragging,  setIsDragging]  = useState(false);
  const [preset,      setPreset]      = useState('engine');
  const [showCustom,  setShowCustom]  = useState(false);
  const [processing,  setProcessing]  = useState(false);

  const fileInputRef = useRef(null);
  const roiCanvasRef = useROICanvas();

  const loadVideo = file => {
    setFile(file);
    if (videoURL) URL.revokeObjectURL(videoURL);
    setVideoURL(URL.createObjectURL(file));
  };

  const handleDrop = e => {
    e.preventDefault(); setIsDragging(false);
    const f = e.dataTransfer.files[0];
    if (f && f.type.startsWith('video/')) loadVideo(f);
  };

  const handleFileSelect = e => {
    const f = e.target.files[0];
    if (f) loadVideo(f);
  };

  const selectPreset = id => {
    setPreset(id);
    setShowCustom(id === 'custom');
  };

  const startAnalysis = () => {
    if (!file) return;
    setProcessing(true);
  };

  return (
    <div className="upload-page page-enter">

      {/* ── NAVBAR ── */}
      <nav className="navbar navbar--light">
        <div className="nav-inner">
          <button className="btn-back" onClick={() => onNavigate('landing')}>← Back</button>
          <Logo onClick={() => onNavigate('landing')} />
          <span className="step-indicator">STEP 1 OF 2 — UPLOAD</span>
        </div>
      </nav>

      <div className="upload-layout">

        {/* ══ LEFT: main upload area ══ */}
        <div className="upload-main">
          <div className="upload-header">
            <h1 className="upload-title">Upload Video</h1>
            <p className="upload-subtitle">
              Upload a video of the target structure or component for motion amplification analysis
            </p>
          </div>

          {/* Dropzone */}
          <div
            className={`dropzone${isDragging ? ' dropzone--drag' : ''}`}
            onClick={() => !videoURL && fileInputRef.current?.click()}
            onDragOver={e => { e.preventDefault(); setIsDragging(true); }}
            onDragLeave={() => setIsDragging(false)}
            onDrop={handleDrop}
          >
            <input
              ref={fileInputRef}
              type="file"
              accept="video/*"
              style={{ display: 'none' }}
              onChange={handleFileSelect}
            />

            {!videoURL ? (
              <div className="dropzone-content">
                <div className="drop-icon">
                  <svg width="36" height="36" viewBox="0 0 24 24" fill="none"
                    stroke="#9ca3af" strokeWidth="1.5" strokeLinecap="round">
                    <polyline points="16 16 12 12 8 16" />
                    <line x1="12" y1="12" x2="12" y2="21" />
                    <path d="M20.39 18.39A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.3" />
                  </svg>
                </div>
                <p className="drop-main">Drag &amp; drop your video</p>
                <p className="drop-sub">or click to browse files</p>
                <p className="drop-formats">MP4 &bull; MOV &bull; AVI &bull; MKV — Up to 2 GB</p>
              </div>
            ) : (
              <div className="dropzone-preview" onClick={e => e.stopPropagation()}>
                <video src={videoURL} controls playsInline preload="metadata" />
                <div className="file-info">
                  {file.name} &nbsp;·&nbsp; {(file.size / (1024 * 1024)).toFixed(1)} MB
                  &nbsp;&nbsp;
                  <button
                    style={{ background: 'none', border: 'none', color: '#E8741A', cursor: 'pointer', fontSize: 12 }}
                    onClick={() => { setFile(null); setVideoURL(null); }}
                  >
                    Remove
                  </button>
                </div>
              </div>
            )}
          </div>

          {/* ROI Canvas */}
          <div className="roi-section">
            <div className="roi-header">
              <div>
                <h3 className="roi-title">Region of Interest</h3>
                <p className="roi-sub">Select the area to focus analysis on</p>
              </div>
              <span className="roi-tag">Full Frame</span>
            </div>
            <div className="roi-canvas-wrap">
              <canvas ref={roiCanvasRef} className="roi-canvas" height={280} />
              <div className="roi-hint">Drag handles to adjust</div>
            </div>
          </div>
        </div>

        {/* ══ RIGHT: sidebar ══ */}
        <div className="upload-sidebar">

          {/* Frequency preset */}
          <div className="sidebar-card">
            <h3 className="sidebar-title">Frequency Preset</h3>
            <p className="sidebar-sub">Select target vibration range</p>
            <div className="preset-list">
              {PRESETS.map(p => (
                <div
                  key={p.id}
                  className={`preset-item${preset === p.id ? ' preset-item--active' : ''}`}
                  onClick={() => selectPreset(p.id)}
                >
                  <div className="preset-info">
                    <span className="preset-name">{p.name}</span>
                    <span className="preset-tag">{p.tag}</span>
                  </div>
                  <span className="preset-desc">{p.desc}</span>
                </div>
              ))}
              {showCustom && (
                <div className="custom-range-inputs">
                  <div className="custom-input-row">
                    <div className="custom-input-group">
                      <label>Min Hz</label>
                      <input type="number" placeholder="e.g. 5" />
                    </div>
                    <div className="custom-input-group">
                      <label>Max Hz</label>
                      <input type="number" placeholder="e.g. 100" />
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Analysis settings */}
          <div className="sidebar-card">
            <h3 className="sidebar-title">Analysis Settings</h3>
            <div className="settings-list">
              {SETTINGS.map(s => (
                <div key={s.name} className="setting-row">
                  <div>
                    <span className="setting-name">{s.name}</span>
                    <span className="setting-hint">{s.hint}</span>
                  </div>
                  <span className="setting-value">{s.value}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Start button */}
          <button
            className={`btn-start${file ? ' btn-start--active' : ''}`}
            onClick={startAnalysis}
          >
            {file ? 'Start Analysis' : 'Upload a Video to Continue'}
          </button>
        </div>
      </div>

      {/* Processing overlay */}
      {processing && (
        <ProcessingOverlay
          onComplete={() => {
            setProcessing(false);
            onAnalysisComplete();
          }}
        />
      )}
    </div>
  );
}
